"""Create a CSV comparison from metrics generated by the training scripts."""
import json
from pathlib import Path
import pandas as pd

def main():
    candidates = [
        ("Custom CNN", Path("outputs/custom_cnn_metrics.json")),
        ("MobileNetV2 Transfer Learning", Path("outputs/mobilenetv2_metrics.json")),
    ]
    rows = []
    for name, path in candidates:
        if path.exists():
            with path.open(encoding="utf-8") as f:
                metrics = json.load(f)
            rows.append({
                "model": name,
                "accuracy": metrics.get("accuracy"),
                "macro_precision": metrics.get("macro_precision"),
                "macro_recall": metrics.get("macro_recall"),
                "macro_f1": metrics.get("macro_f1"),
                "num_test_images": metrics.get("num_test_images"),
            })
    if not rows:
        raise SystemExit("No metric files found. Train and evaluate at least one model first.")
    out = Path("outputs/model_comparison.csv")
    out.parent.mkdir(exist_ok=True)
    frame = pd.DataFrame(rows).sort_values("macro_f1", ascending=False)
    frame.to_csv(out, index=False)
    print(frame.to_string(index=False))
    print(f"\nSaved comparison to {out}")

if __name__ == "__main__":
    main()
